def _build_params(base: Dict[str, Any], overrides: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """
    Create a copy of params with optional overrides or removals (value=None removes key).
    """
    params = dict(base)
    overrides = overrides or {}
    for k, v in overrides.items():
        if v is None and k in params:
            params.pop(k, None)
        elif v is not None:
            params[k] = v
    return params


def _retry_get(api_client, endpoint: str, params: Dict[str, Any], retries: int, backoff: float):
    """
    Simple retry wrapper for GET requests to handle transient issues.
    """
    last_exc = None
    for attempt in range(1, retries + 2):
        try:
            return api_client.get(endpoint=endpoint, params=params)
        except Exception as exc:
            last_exc = exc
            if attempt <= retries:
                time.sleep(backoff * attempt)
    if last_exc:
        raise last_exc


