@pytest.mark.parametrize("missing_param", ["q", "dt"])
def test_astronomy_missing_required_param_returns_error_schema(
    row,
    api_client,
    valid_api_key,
    endpoint,
    swagger_validator,
    request_schema,
    error_response_schema,
    retry_config,
    missing_param,
):
    """
    Negative path: Send request missing a required parameter (q or dt), and validate error schema.
    - Request validation is expected to fail locally (caught and annotated).
    - Server should return an error (non-2xx). We validate the error response schema.
    - This test iterates through all test data rows (astronomy_json.json) for each missing param variant.
    """
    if not valid_api_key:
        pytest.skip("Valid API key not configured. Set it in config.yml or environment variables.")

    retries, backoff = retry_config
    test_rows: List[Dict[str, Any]] = row  # type: ignore[assignment]

    for item in test_rows:
        base_params = {"q": item.get("q"), "dt": item.get("dt"), "key": valid_api_key}
        overrides = {missing_param: None}  # remove the key
        params = _build_params(base_params, overrides)

        # Attempt request validation; expect failure due to missing required field
        try:
            # Only validate against the declared request fields
            filtered = {k: v for k, v in params.items() if k in ("q", "dt")}
            swagger_validator.validate_with_schema(filtered, request_schema)
            # If we get here, local validation did not catch the missing param; that is unexpected.
            pytest.fail(f"Local request validation unexpectedly succeeded for missing required param: {missing_param}")
        except ValidationError:
            # Expected path for negative tests; proceed to call API to observe server-side error behavior.
            pass

        resp = _retry_get(api_client, endpoint, params, retries, backoff)

        # We cannot assert a specific code here due to environment constraints (could be 400/401/403).
        assert not (200 <= resp.status_code < 300), (
            f"Expected non-2xx status for missing '{missing_param}', got {resp.status_code}"
        )

        # Validate error schema if response is JSON
        ct = resp.headers.get("Content-Type", "")
        if "application/json" in ct or "json" in ct:
            try:
                payload = resp.json()
            except ValueError as e:
                pytest.fail(f"Response is not valid JSON for error scenario: {e}\nBody: {resp.text[:500]}")
            swagger_validator.validate_with_schema(payload, error_response_schema)
        else:
            pytest.skip("Error response not JSON; skipping schema validation per content-type.")


